package lf.sandbox.time.auth;

import java.util.Map;
import java.util.UUID;
import java.util.regex.Pattern;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class AuthController {

    private static final Map<String, String> GENERIC_ERROR = Map.of("error", "SBX-E-GENERIC");
    private static final Pattern EMAIL_PATTERN =
            Pattern.compile("^[^@\\s.]+(?:\\.[^@\\s.]+)*@[^@\\s.]+(?:\\.[^@\\s.]+)+$");

    private final AuthService authService;
    private final AuthUser authUser;
    private final BCryptPasswordEncoder passwordEncoder;
    private final String demoEmail;

    public AuthController(
            AuthService authService,
            AuthUser authUser,
            BCryptPasswordEncoder passwordEncoder,
            @Value("${app.auth.b2b-demo-email:demo@sandbox.test}") String demoEmail) {
        this.authService = authService;
        this.authUser = authUser;
        this.passwordEncoder = passwordEncoder;
        this.demoEmail = demoEmail;
    }

    @PostMapping("/api/auth/login")
    public ResponseEntity<?> login(@RequestBody(required = false) Map<String, Object> body) {
        if (body != null && body.containsKey("email")) {
            return loginWithEmail(body);
        }
        if (body == null
                || !(body.get("username") instanceof String username)
                || !(body.get("password") instanceof String password)) {
            return unauthorized();
        }
        return authService
                .login(username, password)
                .<ResponseEntity<?>>map(login -> ResponseEntity.ok(
                        new LoginResponse(login.token(), login.expiresAt().toString())))
                .orElseGet(AuthController::unauthorized);
    }

    private ResponseEntity<?> loginWithEmail(Map<String, Object> body) {
        String correlationId = UUID.randomUUID().toString();
        if (!(body.get("email") instanceof String suppliedEmail)
                || !(body.get("password") instanceof String password)) {
            return invalidCredentials(correlationId);
        }
        String email = suppliedEmail.strip();
        if (password.isEmpty()) {
            return invalidCredentials(correlationId);
        }
        try {
            boolean emailMatches =
                    email.length() <= 254 && EMAIL_PATTERN.matcher(email).matches() && matchesConfiguredEmail(email);
            if (!emailMatches) {
                // Execute the same password-hash work without creating a session.
                passwordEncoder.matches(password, authUser.passwordBcrypt());
                return invalidCredentials(correlationId);
            }
            return authService
                    .login(authUser.username(), password)
                    .<ResponseEntity<?>>map(login ->
                            ResponseEntity.ok(new B2bLoginResponse("AUTHENTICATED", correlationId, login.token())))
                    .orElseGet(() -> invalidCredentials(correlationId));
        } catch (RuntimeException exception) {
            return ResponseEntity.status(503)
                    .body(new B2bLoginFailure("SERVICE_UNAVAILABLE", correlationId, "SBX-B2B-E-NETWORK"));
        }
    }

    private boolean matchesConfiguredEmail(String email) {
        int at = email.lastIndexOf('@');
        int configuredAt = demoEmail.lastIndexOf('@');
        return at > 0
                && configuredAt > 0
                && email.substring(0, at).equals(demoEmail.substring(0, configuredAt))
                && email.substring(at + 1).equalsIgnoreCase(demoEmail.substring(configuredAt + 1));
    }

    private static ResponseEntity<?> invalidCredentials(String correlationId) {
        return ResponseEntity.status(401)
                .body(new B2bLoginFailure("INVALID_CREDENTIALS", correlationId, "SBX-B2B-E-CREDENTIALS"));
    }

    @GetMapping("/api/auth/session")
    public ResponseEntity<?> session(@RequestHeader(name = "Authorization", required = false) String authorization) {
        return authService
                .session(authorization)
                .<ResponseEntity<?>>map(username -> ResponseEntity.ok(new SessionResponse(username)))
                .orElseGet(AuthController::unauthorized);
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<Map<String, String>> invalidLoginBody() {
        return ResponseEntity.status(401).body(GENERIC_ERROR);
    }

    private static ResponseEntity<?> unauthorized() {
        return ResponseEntity.status(401).body(GENERIC_ERROR);
    }

    public record LoginResponse(String token, String expiresAt) {}

    public record SessionResponse(String username) {}

    public record B2bLoginResponse(String outcome, String correlation_id, String token) {}

    public record B2bLoginFailure(String outcome, String correlation_id, String error_code) {}
}

package lf.sandbox.time.auth;

import java.security.SecureRandom;
import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;

@Service
public class AuthService {

    private static final int TOKEN_BYTES = 32;

    private final AuthUser user;
    private final BCryptPasswordEncoder passwordEncoder;
    private final Clock clock;
    private final int maxFailedAttempts;
    private final int lockMinutes;
    private final int sessionMinutes;
    private final SecureRandom random = new SecureRandom();
    private final Map<String, Session> sessions = new HashMap<>();

    private int consecutiveFailures;
    private Instant lockedUntil;

    public AuthService(
            AuthUser user,
            BCryptPasswordEncoder passwordEncoder,
            Clock clock,
            @Value("${app.auth.failed-attempts:5}") int maxFailedAttempts,
            @Value("${app.auth.lock-minutes:15}") int lockMinutes,
            @Value("${app.auth.session-minutes:30}") int sessionMinutes) {
        if (maxFailedAttempts <= 0 || lockMinutes <= 0 || sessionMinutes <= 0) {
            throw new IllegalArgumentException("Invalid authentication policy");
        }
        this.user = user;
        this.passwordEncoder = passwordEncoder;
        this.clock = clock;
        this.maxFailedAttempts = maxFailedAttempts;
        this.lockMinutes = lockMinutes;
        this.sessionMinutes = sessionMinutes;
    }

    public synchronized Optional<LoginResult> login(String username, String password) {
        if (username == null || username.isBlank() || password == null || password.isBlank()) {
            return Optional.empty();
        }

        Instant now = clock.instant();
        if (!user.username().equals(username)) {
            return Optional.empty();
        }
        if (lockedUntil != null) {
            if (now.isBefore(lockedUntil)) {
                return Optional.empty();
            }
            lockedUntil = null;
            consecutiveFailures = 0;
        }

        if (!passwordEncoder.matches(password, user.passwordBcrypt())) {
            consecutiveFailures++;
            if (consecutiveFailures >= maxFailedAttempts) {
                lockedUntil = now.plus(lockMinutes, ChronoUnit.MINUTES);
            }
            return Optional.empty();
        }

        consecutiveFailures = 0;
        byte[] randomBytes = new byte[TOKEN_BYTES];
        random.nextBytes(randomBytes);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);
        Instant expiresAt = now.plus(sessionMinutes, ChronoUnit.MINUTES);
        sessions.put(token, new Session(user.username(), expiresAt));
        return Optional.of(new LoginResult(token, expiresAt));
    }

    public synchronized Optional<String> session(String authorization) {
        if (authorization == null || !authorization.startsWith("Bearer ")) {
            return Optional.empty();
        }
        String token = authorization.substring("Bearer ".length());
        if (token.isBlank()) {
            return Optional.empty();
        }

        Session stored = sessions.get(token);
        if (stored == null) {
            return Optional.empty();
        }
        if (!clock.instant().isBefore(stored.expiresAt())) {
            sessions.remove(token);
            return Optional.empty();
        }
        return Optional.of(stored.username());
    }

    public record LoginResult(String token, Instant expiresAt) {}

    private record Session(String username, Instant expiresAt) {}
}

package lf.sandbox.time.auth;

public record AuthUser(String username, String passwordBcrypt) {

    public AuthUser {
        if (username == null || username.isBlank() || passwordBcrypt == null || passwordBcrypt.isBlank()) {
            throw new IllegalArgumentException("Invalid configured authentication user");
        }
    }
}

-- Persisted B2B accounts, attempts and sessions.
CREATE TABLE IF NOT EXISTS sbx_b2b_accounts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email varchar(254) NOT NULL CHECK (email = btrim(email) AND email LIKE '%@%' AND split_part(email, '@', 2) = lower(split_part(email, '@', 2))),
    password_hash text NOT NULL CHECK (password_hash ~ '^[$]2[aby][$][0-9]{2}[$][./A-Za-z0-9]{53}$'),
    company_code varchar(32) NOT NULL,
    profile varchar(40) NOT NULL CHECK (profile IN ('SBX_B2B_ADMIN_EMPRESA', 'SBX_B2B_APROBADOR', 'SBX_B2B_OPERADOR', 'SBX_B2B_LECTOR_AUDITOR')),
    status varchar(12) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE', 'RESTRICTED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS sbx_b2b_accounts_lower_idx ON sbx_b2b_accounts (lower(email));

CREATE TABLE IF NOT EXISTS sbx_b2b_login_attempts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id bigint REFERENCES sbx_b2b_accounts(id),
    email_normalized varchar(254) NOT NULL CHECK (email_normalized = lower(btrim(email_normalized))),
    outcome varchar(24) NOT NULL CHECK (outcome IN ('INVALID_CREDENTIALS', 'RATE_LIMITED')),
    correlation_id varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sbx_b2b_login_attempts_email_normalized_created_at_idx ON sbx_b2b_login_attempts (email_normalized, created_at);

CREATE TABLE IF NOT EXISTS sbx_b2b_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id bigint NOT NULL REFERENCES sbx_b2b_accounts(id),
    token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at > created_at)
);

CREATE OR REPLACE FUNCTION sbx_b2b_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION sbx_b2b_touch_updated_at() FROM PUBLIC;

DROP TRIGGER IF EXISTS sbx_b2b_accounts_updated_at ON sbx_b2b_accounts;
CREATE TRIGGER sbx_b2b_accounts_updated_at BEFORE UPDATE ON sbx_b2b_accounts
    FOR EACH ROW EXECUTE FUNCTION sbx_b2b_touch_updated_at();
DROP TRIGGER IF EXISTS sbx_b2b_sessions_updated_at ON sbx_b2b_sessions;
CREATE TRIGGER sbx_b2b_sessions_updated_at BEFORE UPDATE ON sbx_b2b_sessions
    FOR EACH ROW EXECUTE FUNCTION sbx_b2b_touch_updated_at();

ALTER TABLE sbx_b2b_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE sbx_b2b_login_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE sbx_b2b_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON sbx_b2b_accounts, sbx_b2b_login_attempts, sbx_b2b_sessions FROM PUBLIC;
REVOKE ALL ON SEQUENCE sbx_b2b_accounts_id_seq, sbx_b2b_login_attempts_id_seq, sbx_b2b_sessions_id_seq FROM PUBLIC;

-- Explicit owner-only policies: no privileges are granted to PUBLIC.
DROP POLICY IF EXISTS sbx_b2b_accounts_owner ON sbx_b2b_accounts;
CREATE POLICY sbx_b2b_accounts_owner ON sbx_b2b_accounts TO CURRENT_USER USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS sbx_b2b_login_attempts_owner ON sbx_b2b_login_attempts;
CREATE POLICY sbx_b2b_login_attempts_owner ON sbx_b2b_login_attempts FOR INSERT TO CURRENT_USER WITH CHECK (true);
DROP POLICY IF EXISTS sbx_b2b_login_attempts_read ON sbx_b2b_login_attempts;
CREATE POLICY sbx_b2b_login_attempts_read ON sbx_b2b_login_attempts FOR SELECT TO CURRENT_USER USING (true);
DROP POLICY IF EXISTS sbx_b2b_sessions_owner ON sbx_b2b_sessions;
CREATE POLICY sbx_b2b_sessions_owner ON sbx_b2b_sessions TO CURRENT_USER USING (true) WITH CHECK (true);

-- The runtime supplies the configured demo bcrypt hash; no literal credential.

-- Reverse only this migration's objects, in foreign-key dependency order.
-- Never cascade into unrelated objects or drop pre-existing application tables.
DROP TABLE IF EXISTS sbx_b2b_sessions;
DROP TABLE IF EXISTS sbx_b2b_login_attempts;
DROP TABLE IF EXISTS sbx_b2b_accounts;
DROP FUNCTION IF EXISTS sbx_b2b_touch_updated_at();
